func setupHandlers(s *Server) {
	// Pages
	s.mux.HandleFunc(
		"GET /not-found/{$}",
		s.handlePageError404GET)
	s.mux.HandleFunc(
		"GET /",
		s.handlePageIndexGET)
	s.mux.HandleFunc(
		"GET /_$/{$}",
		s.handlePageIndexGETStream)
	s.mux.HandleFunc(
		"GET /item/{id}/{$}",
		s.handlePageItemGET)
	s.mux.HandleFunc(
		"GET /item/{id}/_$/{$}",
		s.handlePageItemGETStream)
	s.mux.HandleFunc(
		"PUT /{id}/{$}",
		s.handlePUTEdit)
	s.mux.HandleFunc(
		"POST /{$}",
		s.handlePageIndexPOSTCreate)
	s.mux.HandleFunc(
		"POST /filter/{$}",
		s.handlePageIndexPOSTFilter)
	s.mux.HandleFunc(
		"DELETE /item/{id}/{$}",
		s.handlePageItemDELETEItem)
}

func (s *Server) httpErrIntern(
	w http.ResponseWriter, _ *http.Request,
	_ *datastar.ServerSentEventGenerator, msg string, err error,
) {
	s.logErr(msg, err)
	switch {
	case errors.Is(err, httperr.BadRequest):
		http.Error(w, http.StatusText(http.StatusBadRequest), http.StatusBadRequest)
	case errors.Is(err, httperr.Forbidden):
		http.Error(w, http.StatusText(http.StatusForbidden), http.StatusForbidden)
	case errors.Is(err, httperr.NotFound):
		http.Error(w, http.StatusText(http.StatusNotFound), http.StatusNotFound)
	case errors.Is(err, httperr.Conflict):
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
	default:
		http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
	}
}

func (s *Server) render404(w http.ResponseWriter, r *http.Request) {
	// The URL is claimed by no page. Whatever the app renders for it,
	// the response says so: a cache that stores it and a crawler that
	// reads it both go by the status.
	w.WriteHeader(http.StatusNotFound)
	p := app.PageError404{
		App: s.app,
	}

	body, redirect := p.GET(r)
	if httpRedirect(w, r, redirect, 0) {
		return
	}
	genericHead := s.app.Head(r)

	bodyAttrs := func(w http.ResponseWriter) {
		writeBodyAttrOnVisibilityChange(w)
	}
	if err := s.writeHTML(
		w, r, genericHead, nil, body, bodyAttrs, nil,
	); err != nil {
		s.logErr("rendering PageError404", err)
		return
	}
}

func (s *Server) handlePUTEdit(w http.ResponseWriter, r *http.Request) {
	if !s.checkIsDSReq(w, r) {
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, DefaultBodySizeLimit)
	var signals struct {
		Title       string `json:"title"`
		Description string `json:"description"`
		Done        bool   `json:"done"`
		Due         string `json:"due"`
	}
	if err := datastar.ReadSignals(r, &signals); err != nil {
		s.httpErrBad(w, "reading signals", err)
		return
	}

	q := r.URL.Query()
	var query struct {
		Toggle bool `query:"toggle"`
	}
	{
		if q := q.Get("toggle"); q != "" {
			b, err := strconv.ParseBool(q)
			if err != nil {
				s.httpErrBad(w, "unexpected value for query parameter: toggle", err)
				return
			}
			query.Toggle = b
		}
	}

	var path struct {
		ID string `path:"id"`
	}
	path.ID = r.PathValue("id")

	dispatch := func(
		e1 app.EventTodoUpdated,
	) error {
		{
			j, err := json.Marshal(e1)
			if err != nil {
				return fmt.Errorf("marshaling EventTodoUpdated JSON: %w", err)
			}
			err = s.messageBroker.Publish(r.Context(), s.messageBrokerMetrics, EvSubjTodoUpdated, j)
			if err != nil {
				return fmt.Errorf("publishing subject %q: %w", EvSubjTodoUpdated, err)
			}
		}
		return nil
	}
	err := s.app.PUTEdit(r, path, query, signals, dispatch)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling action App.Edit", err)
		return
	}
}

