func (s *Server) handlePageIndexGET(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		s.render404(w, r)
		return
	}

	q := r.URL.Query()
	var query struct {
		Search string `query:"q" reflectsignal:"search"`
		Filter string `query:"filter" reflectsignal:"filter"`
		Sort   string `query:"sort" reflectsignal:"sort"`
	}
	query.Search = q.Get("q")
	query.Filter = q.Get("filter")
	query.Sort = q.Get("sort")

	// Mint the per-instance identifier for this page load.
	// The client echoes this value on action requests and on the SSE
	// stream connect via the Datapages-Instance header.
	instanceID, err := s.signStateInstanceID()
	if err != nil {
		s.httpErrIntern(w, r, nil, "minting state instance", err)
		return
	}
	w.Header().Set(stateInstanceIDHeader, instanceID)
	// The page carries an identifier that stands for one tab's state.
	// A cache that hands it to a second visitor hands over the state.
	w.Header().Set("Cache-Control", "no-store")

	p := app.PageIndex{
		App: s.app,
	}
	body, err := p.GET(r, query)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling PageIndex.GET", err)
		return
	}
	genericHead := s.app.Head(r)

	bodyAttrs := func(w http.ResponseWriter) {
		writeBodyAttrOnVisibilityChange(w)

		_, _ = io.WriteString(w, `data-signals:search="'`)
		_, _ = io.WriteString(w, query.Search)
		_, _ = io.WriteString(w, `'"`)

		_, _ = io.WriteString(w, `data-signals:filter="'`)
		_, _ = io.WriteString(w, query.Filter)
		_, _ = io.WriteString(w, `'"`)

		_, _ = io.WriteString(w, `data-signals:sort="'`)
		_, _ = io.WriteString(w, query.Sort)
		_, _ = io.WriteString(w, `'"`)
	}

	bodySuffix := func(w http.ResponseWriter) {

		_, _ = io.WriteString(w, `data-init="@get('/_$/')"`)

		_, _ = io.WriteString(w, `data-effect="const params = new URLSearchParams();
			if ($search) params.set('q', $search);
			if ($filter) params.set('filter', $filter);
			if ($sort) params.set('sort', $sort);
			const query = params.toString();
			window.history.replaceState(null, '', query ? '/?' + query : '/');
		"`)
	}

	if err := s.writeHTML(
		w, r, genericHead, nil, body, bodyAttrs, bodySuffix,
	); err != nil {
		s.logErr("rendering PageIndex", err)
		return
	}
}

func (s *Server) handlePageIndexGETStream(w http.ResponseWriter, r *http.Request) {
	if !s.checkIsDSReq(w, r) {
		return
	}

	var signals struct {
		Search string `json:"search"`
		Filter string `json:"filter"`
		Sort   string `json:"sort"`
	}
	if err := datastar.ReadSignals(r, &signals); err != nil {
		s.httpErrBad(w, "reading signals", err)
		return
	}

	instanceID := r.Header.Get(stateInstanceIDHeader)
	if !s.verifyStateInstanceID(instanceID) {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}
	if _, live := s.lookupStateIndex(instanceID); !live && !s.stateHasCapacity() {
		w.Header().Set("Retry-After", "5")
		http.Error(w,
			http.StatusText(http.StatusServiceUnavailable),
			http.StatusServiceUnavailable)
		return
	}
	var slot *stateSlotStateIndex

	p := app.PageIndex{
		App: s.app,
	}
	s.handleStreamRequest(w, r, evSubjPageIndex(),
		func(
			streamID uint64,
			sse *datastar.ServerSentEventGenerator,
		) error {
			if existing, ok := s.reconnectStateIndex(instanceID, streamID); ok {
				slot = existing
			} else {
				slot = s.allocateStateIndex(instanceID, streamID)
			}
			// A stream that gets no slot never opens: the event loop and the
			// close hook run only once this hook has returned nil,
			// which is why neither of them checks again.
			if slot == nil {
				return errStateAtCapacity
			}
			// The close hook is wired up only once this one has returned nil.
			// An open that ends any other way hands the instance to the grace
			// timer here, since nothing else is left to give it back.
			opened := false
			defer func() {
				if !opened {
					s.closeStreamStateIndex(instanceID, streamID)
				}
			}()
			slot.mu.Lock()
			defer slot.mu.Unlock()
			if err := p.StreamOpen(r, streamID, slot.state, signals); err != nil {
				return err
			}
			opened = true
			return nil
		},
		func(streamID uint64) {
			s.closeStreamStateIndex(instanceID, streamID)
		},
		func(
			streamID uint64,
			sse *datastar.ServerSentEventGenerator, ch <-chan msgbroker.Message,
		) {
			for msg := range ch {
				switch msg.Subject {
				case EvSubjTodoUpdated:
					var e app.EventTodoUpdated
					if err := json.Unmarshal(msg.Data, &e); err != nil {
						s.logErr("unmarshaling EventTodoUpdated JSON", err)
						continue
					}
					slot.mu.Lock()
					if slot.dead {
						slot.mu.Unlock()
						continue
					}
					if err := p.OnTodoUpdated(e, sse, slot.state); err != nil {
						s.logErr("handling PageIndex.OnTodoUpdated", err)
					}
					slot.mu.Unlock()
				}
			}
		})
}

